def compute_4_connected_components(grid):
    """Compute 4-connected component sizes for each color"""
    bg_color = 1  # The dominant background
    rows = len(grid)
    cols = len(grid[0])

    # Track which cells have been assigned to components
    component_size = {}  # (r,c) -> size of its component

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color:
                continue

            # This is a non-background cell, compute its component
            color = grid[r][c]
            if (r,c) in component_size:
                continue

            visited = set()
            stack = [(r, c)]
            size = 0

            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                size += 1

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            stack.append((nr, nc))

            # Store size for all cells in this component
            for (cr, cc) in visited:
                component_size[(cr, cc)] = size

    return component_size

